(()=>{
const F=window.AuroraFinance,q=s=>document.querySelector(s),brl=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),n=id=>Number(q('#'+id).value),val=id=>q('#'+id).value;
const source='https://www.gov.br/cidades/pt-br/acesso-a-informacao/acoes-e-programas/habitacao/programa-minha-casa-minha-vida/mcmv-fgts',classSource='https://www.gov.br/cidades/pt-br/acesso-a-informacao/acoes-e-programas/habitacao/programa-minha-casa-minha-vida/minha-casa-minha-vida-classe-media/minha-casa-minha-vida-classe-media-1';
const numeric=(id,label,value,min=0,max=1e8,step='.01')=>`<label>${label}<input id="${id}" type="number" value="${value}" min="${min}" max="${max}" step="${step}" required></label>`;
const now=new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit'}).format(new Date()),mi=F.monthIndex(now),start=F.monthString(mi+1),end=F.monthString(mi+24);
const dialog=document.createElement('dialog');dialog.id='financeDialog';dialog.setAttribute('aria-labelledby','financeTitle');dialog.innerHTML=`<div class="finance-head"><div><p class="eyebrow">COMPRA PLANEJADA</p><h2 id="financeTitle">Financiamento & entrada</h2><p id="financeUnit"></p></div><button id="closeFinance" aria-label="Fechar simulador">×</button></div><div class="finance-intro">Estimativa independente, sem conexão com a Caixa e sem aprovação de crédito. Valores iniciais são exemplos. Dados ficam apenas nesta sessão.</div><div class="finance-layout"><div class="finance-inputs"><section><h3><span>01</span> Estime o financiamento</h3><p class="muted">Imóvel novo/em construção em São Paulo (capital). Regras consultadas em 06/10/2026.</p><form id="loanForm"><div class="form-grid">${numeric('loanIncome','Renda familiar bruta (R$/mês)',10000,1,1000000)}${numeric('loanDebts','Outras parcelas e compromissos (R$/mês)',0,0,1000000)}<label>Linha de crédito<select id="loanProduct"><option value="classe">MCMV Classe Média · até R$ 600 mil</option><option value="faixa">MCMV · faixa pela renda</option></select></label><label>Sistema de amortização<select id="loanSystem"><option value="SAC">SAC · prestação decrescente</option><option value="PRICE">Price · prestação-base constante</option></select></label>${numeric('loanAge','Idade do mais velho ao iniciar o financiamento',35,18,80.5)}${numeric('loanMonths','Prazo desejado (meses)',420,1,420,1)}${numeric('loanQuota','Cota de financiamento simulada (%)',80,1,90)}${numeric('loanCosts','Reserva para seguros/tarifas (R$/mês)',150,0,100000)}${numeric('loanFgts','FGTS a utilizar (R$)',0)}${numeric('loanSubsidy','Subsídio já confirmado pelo banco (R$)',0,0,55000)}<label class="checkline"><input id="loanCotista" type="checkbox" checked>Cotista do FGTS conforme os critérios do banco</label><label class="checkline"><input id="loanProperty" type="checkbox">Já possui imóvel ou financiamento habitacional</label></div><p class="muted">A reserva de R$ 150 é uma hipótese editável, não uma cotação de seguros. A cota de 80% é um parâmetro inicial; o banco pode financiar menos. O subsídio começa em zero e não é calculado automaticamente.</p></form></section><section><h3><span>02</span> Distribua sua entrada</h3><form id="planForm"><div class="form-grid"><label>Valor a planejar<select id="entryMode"><option value="estimate">Entrada própria desta simulação</option><option value="manual">Valor informado pela construtora</option></select></label>${numeric('manualEntry','Entrada informada (R$)',100000)}<label>Mês da contratação<input id="planContract" type="month" value="${now}" required></label><label>Primeira parcela mensal<input id="planStart" type="month" value="${start}" required></label><label>Última mensal / chaves<input id="planEnd" type="month" value="${end}" required></label>${numeric('planSignal','Sinal na contratação (R$)',10000)}${numeric('planMonthly','Parcela mensal que pretende pagar (R$)',2000)}${numeric('planCapacity','Orçamento mensal para a entrada (R$)',2500)}${numeric('planKeys','Pagamento adicional nas chaves (R$)',15000)}${numeric('planCorrection','Correção anual projetada (%)',0,0,30)}</div><p class="muted">Mensais incluem o primeiro e o último mês. Sinal, extras e chaves são adicionais às mensais. A data de chaves é uma hipótese editável, não a data de lançamento.</p><h4>Pagamentos extras</h4><div id="extraRows"></div><button type="button" id="addExtra">Adicionar anual, semestral ou avulsa</button><p class="muted">Extras se repetem a partir do primeiro vencimento informado até as chaves. Meses acima do orçamento ficam destacados, inclusive sinal e chaves.</p></form></section></div><aside class="finance-results"><div id="loanResult" aria-live="polite"></div><div id="planResult" aria-live="polite"></div></aside></div><section class="finance-calendar"><div class="calendar-head"><div><h3>Calendário da entrada</h3><p id="calendarNote" class="muted"></p></div><button id="downloadPlan">Baixar planejamento CSV</button></div><div class="table-scroll"><table><thead><tr><th>Mês</th><th>Sinal</th><th>Mensal</th><th>Extras</th><th>Chaves</th><th>Correção</th><th>Total do mês</th><th>Acumulado</th></tr></thead><tbody id="calendarRows"></tbody></table></div></section><details class="finance-method"><summary>Premissas, limites e fontes do cálculo</summary><p>Renda disponível estimada: 30% da renda bruta, menos os compromissos declarados e a reserva de seguros/tarifas. Taxa nominal anual dividida por 12. Financiamento limitado pela renda, pela cota e pelo preço menos FGTS e subsídio. SAC considera a primeira prestação, a maior; Price usa a prestação-base constante. Seguros reais podem variar por idade, saldo e composição de renda.</p><p>Prazo de até 420 meses, limitado pela hipótese de idade de 80 anos e 6 meses ao término. Informe a idade prevista no início do financiamento, inclusive espera pela obra. Não há cálculo de CET, TR futura, juros de evolução de obra, ITBI ou cartório. A prestação apresentada é a da fase de amortização, não o encargo durante a construção.</p><p>Entrada e financiamento são fluxos distintos. O calendário não soma parcelas do banco aos pagamentos à construtora. Se houver sobreposição contratual, ela deve ser analisada à parte. Correção da entrada é uma projeção uniforme sobre cada pagamento desde o mês da contratação; não é previsão de INCC nem reprodução de um contrato. O saldo a distribuir é calculado em reais do mês da contratação, sem misturar correção com entrada-base.</p><p>Na Classe Média, o limite normativo para imóvel novo é 90% no SAC e 80% no Price; a cota efetiva depende do banco. Nas demais faixas, este estudo usa no máximo 80% como premissa conservadora a confirmar. Renda e preço não bastam para confirmar elegibilidade, uso do FGTS ou subsídio. A modalidade Classe Média pode ser testada separadamente quando o preço superar o teto da faixa pela renda.</p><p><a href="${source}" target="_blank" rel="noreferrer">Faixas, taxas e tetos · Ministério das Cidades</a> · <a href="${classSource}" target="_blank" rel="noreferrer">Regras da Classe Média</a> · <a href="https://www.caixa.gov.br/voce/habitacao/lote-urbanizado/Paginas/default.aspx" target="_blank" rel="noreferrer">Referências de idade e comprometimento · Caixa</a> · <a href="https://simuladorhabitacao.caixa.gov.br/home" target="_blank" rel="noreferrer">Simulador oficial da Caixa</a></p></details>`;
document.body.append(dialog);let unit=null,loan=null,plan=null,extraId=0;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function card(label,value){return `<div class="result-value"><span>${label}</span><strong>${value}</strong></div>`;}
function params(){return {price:unit.preco,income:n('loanIncome'),debts:n('loanDebts'),costs:n('loanCosts'),age:n('loanAge'),months:n('loanMonths'),quota:n('loanQuota'),fgts:n('loanFgts'),subsidy:n('loanSubsidy'),product:val('loanProduct'),system:val('loanSystem'),cotista:q('#loanCotista').checked,hasProperty:q('#loanProperty').checked};}
function update(){if(!unit)return;loan=null;plan=null;q('#downloadPlan').disabled=true;q('#manualEntry').disabled=val('entryMode')!=='manual';q('#calendarRows').innerHTML='';q('#calendarNote').textContent='';try{if(!q('#loanForm').checkValidity())throw Error('Preencha os campos de financiamento com valores válidos.');loan=F.financing(params());if(!loan.valid)q('#loanResult').innerHTML=`<div class="result-box warning"><h3>Revise o enquadramento</h3>${loan.errors.map(e=>`<p>${esc(e)}</p>`).join('')}<p class="muted">Você ainda pode planejar uma entrada informada pela construtora.</p></div>`;else q('#loanResult').innerHTML=`<div class="result-box"><p class="eyebrow">${loan.classe?'MCMV CLASSE MÉDIA':'MCMV · FAIXA '+loan.faixa}</p><h3>Estimativa para sua renda</h3>${card('Financiamento estimado',brl(loan.principal))}${card('Entrada em recursos próprios',brl(loan.cash))}<div class="result-pair">${card('Primeira prestação',brl(loan.first))}${card('Última prestação',brl(loan.last))}</div><p>${loan.months} meses · ${loan.annual.toLocaleString('pt-BR')}% a.a. nominal · ${val('loanSystem')}</p><p class="muted">FGTS: ${brl(n('loanFgts'))} · subsídio informado: ${brl(n('loanSubsidy'))}. Não entram novamente no planejamento da entrada própria.</p>${loan.warnings.map(e=>`<p class="warning-text">${esc(e)}</p>`).join('')}<button id="downloadLoan">Baixar parcelas do financiamento</button><p class="muted">Não representa aprovação. Seguros/tarifas são a reserva informada; TR e evolução de obra não estão incluídas.</p></div>`;}catch(e){q('#loanResult').innerHTML=`<div class="result-box warning">${esc(e.message)}</div>`;}
q('#downloadLoan')?.addEventListener('click',()=>saveCSV('aurora-financiamento.csv',[['Apartamento',unit.unidade],['Preço',unit.preco],['Renda',n('loanIncome')],['Taxa nominal anual',loan.annual],['Sistema',val('loanSystem')],['Reserva mensal seguros/tarifas',n('loanCosts')],['Premissas','Sem TR futura, CET ou juros de obra; estimativa sem aprovação'],['Mes','Amortizacao','Juros','Prestacao_com_reserva','Saldo'],...loan.rows.map(r=>[r.month,r.principal,r.interest,r.payment,r.balance])]));
try{if(!q('#planForm').checkValidity())throw Error('Preencha os campos de entrada com valores e datas válidos.');if(val('entryMode')==='estimate'&&!loan?.valid)throw Error('Conclua uma simulação válida ou escolha “Valor informado pela construtora”.');const target=val('entryMode')==='manual'?n('manualEntry'):loan.cash;plan=F.planning({target,contract:val('planContract'),start:val('planStart'),end:val('planEnd'),signal:n('planSignal'),monthly:n('planMonthly'),capacity:n('planCapacity'),keys:n('planKeys'),correction:n('planCorrection'),extras:[...q('#extraRows').children].map(r=>({date:r.querySelector('[data-date]').value,amount:Number(r.querySelector('[data-amount]').value),every:Number(r.querySelector('[data-every]').value)}))});const over=plan.gap<-.005; q('#planResult').innerHTML=`<div class="result-box ${plan.gap>.005?'pending':'complete'}"><p class="eyebrow">PLANEJAMENTO DA ENTRADA</p>${card('Entrada própria a distribuir',brl(target))}${card(over?'Planejado a mais':plan.gap>.005?'Ainda falta distribuir':'Entrada-base distribuída',brl(Math.abs(plan.gap)))}<progress max="${Math.max(target,1)}" value="${Math.min(plan.baseTotal,target)}"></progress><p>${brl(plan.baseTotal)} planejados em valores-base.</p><p><b>${plan.count} parcelas mensais</b> · ${plan.over} meses acima do orçamento.</p>${plan.gap>.005?`<p>Para completar mantendo os extras, a mensal-base seria <b>${brl(plan.monthlySuggestion)}</b>, com ajuste de centavos na última parcela.</p>`:''}${n('planCorrection')>0?`<p>Total de desembolsos projetados: <b>${brl(plan.total)}</b>, incluindo ${brl(plan.correction)} de correção estimada sobre o que foi planejado.</p>`:'<p class="muted">Valores sem correção contratual.</p>'}${over?'<p class="warning-text">Reduza os pagamentos planejados para evitar exceder a entrada.</p>':''}</div>`;
q('#calendarRows').innerHTML=plan.rows.map(r=>`<tr class="${r.over?'over-budget':''}"><th scope="row">${r.date.slice(5)}/${r.date.slice(0,4)}${r.over?'<small>Acima do orçamento</small>':''}</th>${['signal','monthly','extras','keys','correction','total','cumulative'].map(k=>`<td>${brl(r[k])}</td>`).join('')}</tr>`).join('');q('#calendarNote').textContent=`${plan.count} mensais de ${val('planStart').split('-').reverse().join('/')} a ${val('planEnd').split('-').reverse().join('/')}. Valores em reais; pagamentos extras são somados, não substituem a mensal.`;q('#downloadPlan').disabled=false;}catch(e){q('#planResult').innerHTML=`<div class="result-box warning">${esc(e.message)}</div>`;}}
function saveCSV(name,rows){const text='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
q('#downloadPlan').onclick=()=>{if(!plan)return;saveCSV('aurora-planejamento-entrada.csv',[['Apartamento',unit.unidade],['Preço',unit.preco],['Entrada_base',val('entryMode')==='manual'?n('manualEntry'):loan.cash],['Origem',val('entryMode')==='manual'?'Informada pela construtora':'Estimativa independente MCMV'],['Saldo_base_a_distribuir',plan.gap],['Correcao_anual_projetada_percentual',n('planCorrection')],['Orcamento_mensal',n('planCapacity')],['Premissas','Sem aprovação de crédito; correção hipotética; não inclui encargos de obra'],['Mes','Sinal','Mensal','Extras','Chaves','Correcao','Total','Acumulado'],...plan.rows.map(r=>[r.date,r.signal,r.monthly,r.extras,r.keys,r.correction,r.total,r.cumulative])]);};
q('#addExtra').onclick=()=>{const row=document.createElement('div');row.className='extra-row';const id=++extraId;row.innerHTML=`<label>Primeiro vencimento<input data-date type="month" value="${val('planStart')}" required></label><label>Valor (R$)<input data-amount type="number" min="0" max="100000000" step=".01" value="10000" required></label><label>Frequência<select data-every><option value="0">Uma vez</option><option value="6">Semestral</option><option value="12">Anual</option></select></label><button type="button" aria-label="Remover pagamento extra ${id}">×</button>`;row.querySelector('button').onclick=()=>{row.remove();update()};q('#extraRows').append(row);update();};
for(const id of ['loanForm','planForm']){q('#'+id).addEventListener('input',update);q('#'+id).addEventListener('change',update);q('#'+id).onsubmit=e=>e.preventDefault();}
q('#closeFinance').onclick=()=>dialog.close();window.openAuroraFinance=u=>{unit={...u};q('#financeUnit').textContent=`Apartamento ${u.unidade} · ${u.area} m² · ${brl(u.preco)} · ${u.status}`;dialog.showModal();dialog.scrollTop=0;update();};
})();
